@startuml

class FurnitureLine {
  + name: string
}

class Furniture {
  + type: string
  + reference: string
  + sellingPrice: double
}

class Component {
  + code: int
  + manufacturingPrice: double
  + type: string
}

class PieceComponent {
  + quantity: int
}

class Store {
  + address: string
  + faxNumber: string
}

class Order {
  + orderNumber: string
  + date: date
}

class OrderLine {
  + quantity: int
}

FurnitureLine "1" *-- "*" Furniture
Furniture "*" -- "*" Component : composed of
Furniture "1" -- "*" PieceComponent
Component "1" -- "*" PieceComponent

Store "1" -- "*" Order : places
Order "1" -- "*" OrderLine
OrderLine "*" -- "1" Furniture

@enduml

